import{_ as s,o as n,c as e,a6 as p}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"FastCGI、uWSGI 与 gRPC","description":"fastcgi_param 的必填项、PATH_INFO 与安全陷阱、uwsgi/scgi 对照与 grpc_pass。","frontmatter":{"title":"FastCGI、uWSGI 与 gRPC","description":"fastcgi_param 的必填项、PATH_INFO 与安全陷阱、uwsgi/scgi 对照与 grpc_pass。","source":"https://daiw.org/manual/nginx/fastcgi-grpc"},"headers":[],"relativePath":"manual/tools/nginx/fastcgi-grpc.md","filePath":"manual/tools/nginx/fastcgi-grpc.md"}'),t={name:"manual/tools/nginx/fastcgi-grpc.md"};function i(c,a,l,r,o,d){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="fastcgi、uwsgi-与-grpc" tabindex="-1">FastCGI、uWSGI 与 gRPC <a class="header-anchor" href="#fastcgi、uwsgi-与-grpc" aria-label="Permalink to &quot;FastCGI、uWSGI 与 gRPC&quot;">​</a></h1><p>除 HTTP 外，nginx 还能直接说 FastCGI、uwsgi、SCGI、gRPC 四种上游协议。它们的指令高度同构——<code>*_pass</code>、<code>*_param</code>、<code>*_buffering</code>、<code>*_read_timeout</code> 一一对应。</p><h2 id="fastcgi" tabindex="-1">FastCGI <a class="header-anchor" href="#fastcgi" aria-label="Permalink to &quot;FastCGI&quot;">​</a></h2><p>最常见的用途是 PHP-FPM。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location ~ \\.php$ {</span></span>
<span class="line"><span>    try_files $uri =404;                       # ← 必需，见下</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    fastcgi_pass  127.0.0.1:9000;              # 或 unix:/run/php-fpm.sock</span></span>
<span class="line"><span>    fastcgi_index index.php;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    include       fastcgi_params;              # 发行版自带的公共参数</span></span>
<span class="line"><span>    fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;</span></span>
<span class="line"><span>    fastcgi_param PATH_INFO       $fastcgi_path_info;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h3 id="fastcgi-pass" tabindex="-1">fastcgi_pass <a class="header-anchor" href="#fastcgi-pass" aria-label="Permalink to &quot;fastcgi\\_pass&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    fastcgi_pass address;</span></span>
<span class="line"><span>上下文:  location, if in location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>与 <a href="/Front2Full/manual/tools/nginx/proxy"><code>proxy_pass</code></a> 不同，<strong><code>fastcgi_pass</code> 不带 URI</strong>——FastCGI 是通过参数传递路径信息的，没有「URI 替换」这回事。</p><p>地址可以是 <code>host:port</code>、<code>unix:/path</code>，或一个 <a href="/Front2Full/manual/tools/nginx/upstream">upstream 名</a>。</p><h3 id="script-filename-是必填的" tabindex="-1">SCRIPT_FILENAME 是必填的 <a class="header-anchor" href="#script-filename-是必填的" aria-label="Permalink to &quot;SCRIPT\\_FILENAME 是必填的&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>没有它 PHP-FPM 不知道要执行哪个文件</strong>，会返回 <code>No input file specified</code> 或空白页。</p><p>多数发行版的 <code>fastcgi_params</code> 文件里<strong>故意不含</strong>这一行——因为它依赖具体的 <code>root</code> 配置，必须由使用者自己写。这是「配了 include 还是不工作」的常见原因。</p><p><code>$document_root</code> vs <code>$realpath_root</code> 的选择见<a href="/Front2Full/manual/tools/nginx/variables">变量章</a>：符号链接部署 + OPcache 时通常需要 <code>$realpath_root</code>。</p><h3 id="那个-try-files-uri-404-为什么必需" tabindex="-1">那个 <code>try_files $uri =404;</code> 为什么必需 <a class="header-anchor" href="#那个-try-files-uri-404-为什么必需" aria-label="Permalink to &quot;那个 \`try_files $uri =404;\` 为什么必需&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location ~ \\.php$ {</span></span>
<span class="line"><span>    try_files $uri =404;    # ← 少了这行是安全漏洞</span></span>
<span class="line"><span>    fastcgi_pass ...;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>这是 nginx + PHP 最著名的安全陷阱。</strong></p><p>没有这行时，请求 <code>/uploads/evil.jpg/x.php</code> 会：</p><ol><li>匹配 <code>location ~ \\.php$</code>（URI 以 <code>.php</code> 结尾）；</li><li><code>SCRIPT_FILENAME</code> 被拼成 <code>/var/www/uploads/evil.jpg/x.php</code>；</li><li>PHP 的 <code>cgi.fix_pathinfo</code> 默认会向上回退，找到真实存在的 <code>/var/www/uploads/evil.jpg</code>；</li><li><strong>把上传的图片当 PHP 执行</strong> → 任意代码执行。</li></ol><p><code>try_files $uri =404;</code> 先确认「这个 <code>.php</code> 文件真的存在」，不存在直接 404，切断了整条链路。</p><p>另一半防护在 PHP 侧：<code>php.ini</code> 里设 <code>cgi.fix_pathinfo=0</code>。<strong>两边都做才稳妥。</strong></p><h3 id="path-info" tabindex="-1">PATH_INFO <a class="header-anchor" href="#path-info" aria-label="Permalink to &quot;PATH\\_INFO&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fastcgi_split_path_info ^(.+\\.php)(/.+)$;</span></span>
<span class="line"><span>fastcgi_param PATH_INFO $fastcgi_path_info;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>fastcgi_split_path_info</code> 用正则把 URI 切成「脚本路径」与「路径信息」两段，分别填进 <code>$fastcgi_script_name</code> 与 <code>$fastcgi_path_info</code>。</p><p>框架路由（<code>/index.php/user/1</code>）需要它。不用这种路由风格时不必配。</p><h3 id="fastcgi-的-keepalive" tabindex="-1">FastCGI 的 keepalive <a class="header-anchor" href="#fastcgi-的-keepalive" aria-label="Permalink to &quot;FastCGI 的 keepalive&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>upstream php {</span></span>
<span class="line"><span>    server unix:/run/php-fpm.sock;</span></span>
<span class="line"><span>    keepalive 8;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>location ~ \\.php$ {</span></span>
<span class="line"><span>    fastcgi_pass      php;</span></span>
<span class="line"><span>    fastcgi_keep_conn on;        # ← FastCGI 专用，必需</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><a href="/Front2Full/manual/tools/nginx/upstream">前一章</a>提过：<strong>FastCGI 需要额外的 <code>fastcgi_keep_conn on;</code></strong>，只配 upstream 的 <code>keepalive</code> 不生效。</p><h3 id="缓冲与超时" tabindex="-1">缓冲与超时 <a class="header-anchor" href="#缓冲与超时" aria-label="Permalink to &quot;缓冲与超时&quot;">​</a></h3><p>与 proxy 完全同构，只是前缀不同：</p><table tabindex="0"><thead><tr><th>FastCGI</th><th>对应 proxy</th><th>默认</th></tr></thead><tbody><tr><td><code>fastcgi_buffering</code></td><td><code>proxy_buffering</code></td><td><code>on</code></td></tr><tr><td><code>fastcgi_buffer_size</code></td><td><code>proxy_buffer_size</code></td><td>4k</td></tr><tr><td><code>fastcgi_buffers</code></td><td><code>proxy_buffers</code></td><td>8 4k</td></tr><tr><td><code>fastcgi_connect_timeout</code></td><td><code>proxy_connect_timeout</code></td><td>60s</td></tr><tr><td><code>fastcgi_read_timeout</code></td><td><code>proxy_read_timeout</code></td><td>60s</td></tr><tr><td><code>fastcgi_next_upstream</code></td><td><code>proxy_next_upstream</code></td><td>error timeout</td></tr></tbody></table><p>PHP 长任务超时要同时调 nginx 的 <code>fastcgi_read_timeout</code> 与 PHP 的 <code>max_execution_time</code>——<strong>两边取较小值生效</strong>。</p><h2 id="uwsgi-与-scgi" tabindex="-1">uwsgi 与 SCGI <a class="header-anchor" href="#uwsgi-与-scgi" aria-label="Permalink to &quot;uwsgi 与 SCGI&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location / {</span></span>
<span class="line"><span>    include     uwsgi_params;</span></span>
<span class="line"><span>    uwsgi_pass  unix:/run/uwsgi/app.sock;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>指令集与 FastCGI 一一对应（<code>uwsgi_param</code>、<code>uwsgi_buffering</code>、<code>uwsgi_read_timeout</code>…），用于 Python WSGI 应用。</p><p><strong>uwsgi 与 SCGI 都不支持 keepalive</strong>（官方明确说明）。所以这两种协议下配 upstream <code>keepalive</code> 无效——每个请求都是新连接。</p><p>现代 Python 部署更多用 <code>proxy_pass</code> 直连 gunicorn/uvicorn 的 HTTP 端口，从而能用上 HTTP keepalive。</p><h2 id="grpc" tabindex="-1">gRPC <a class="header-anchor" href="#grpc" aria-label="Permalink to &quot;gRPC&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    listen 443 ssl;</span></span>
<span class="line"><span>    http2  on;                    # gRPC 必须走 HTTP/2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    location / {</span></span>
<span class="line"><span>        grpc_pass grpc://127.0.0.1:50051;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>TLS 上游用 <code>grpcs://</code>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grpc_pass grpcs://backend.internal:50051;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>要点：</p><ul><li><strong>必须开 <a href="/Front2Full/manual/tools/nginx/http2-http3">HTTP/2</a></strong>——gRPC 基于 HTTP/2，没有 h2 就不成立。</li><li>指令族同构：<code>grpc_set_header</code>、<code>grpc_connect_timeout</code>、<code>grpc_read_timeout</code>、<code>grpc_next_upstream</code>。</li><li><strong>流式 RPC 要调大 <code>grpc_read_timeout</code></strong>——服务端流可能长时间无数据。</li><li>上游是 upstream 组时写 <code>grpc_pass grpc://组名;</code>。</li></ul><p>按服务分流：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /helloworld.Greeter/ {</span></span>
<span class="line"><span>    grpc_pass grpc://greeter_backend;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>location /routeguide.RouteGuide/ {</span></span>
<span class="line"><span>    grpc_pass grpc://route_backend;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>gRPC 的路径就是 <code>/包名.服务名/方法名</code>，所以用普通的<a href="/Front2Full/manual/tools/nginx/location">前缀 location</a> 就能按服务路由。</p><h2 id="四种协议对照" tabindex="-1">四种协议对照 <a class="header-anchor" href="#四种协议对照" aria-label="Permalink to &quot;四种协议对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>FastCGI</th><th>uwsgi</th><th>SCGI</th><th>gRPC</th></tr></thead><tbody><tr><td>典型场景</td><td>PHP-FPM</td><td>Python WSGI</td><td>通用</td><td>微服务 RPC</td></tr><tr><td>pass 指令</td><td><code>fastcgi_pass</code></td><td><code>uwsgi_pass</code></td><td><code>scgi_pass</code></td><td><code>grpc_pass</code></td></tr><tr><td>传参方式</td><td><code>fastcgi_param</code></td><td><code>uwsgi_param</code></td><td><code>scgi_param</code></td><td>HTTP/2 头</td></tr><tr><td>keepalive</td><td>✅（需 <code>fastcgi_keep_conn</code>）</td><td>❌</td><td>❌</td><td>✅（h2 原生）</td></tr><tr><td>要求 HTTP/2</td><td>否</td><td>否</td><td>否</td><td><strong>是</strong></td></tr></tbody></table><p>下一篇：<a href="/Front2Full/manual/tools/nginx/ssl">SSL/TLS 配置</a>。</p>`,49)])])}const b=s(t,[["render",i]]);export{g as __pageData,b as default};
